(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0007.js"] = [{"id":"glyph-kai-6d41","script":"kai","character":"流","reading":"liú","description":"liú：(1)液体移动～水。～汗。～血。～泪。～程。～泻。～质。～水不腐」～浃背。随波逐～（随着波浪起伏，跟着流水漂荡，喻没有主见，随着潮流走）。\n(2)像水那样流动不定～转（zhuǎn）。～通。～寇。～浪。～离。～散。～失。～沙。～露。～萤。\n(3)传播～言。～传。～芳。～弊。～毒。～行（xíng）。\n(4)指江河的流水河～。江～。溪～。激～。奔～。\n(5)像水流的东西气～。暖～。电～。\n(6)向坏的方面转变～于形式。\n(7)旧时的刑罚，把犯人送到荒远的地方去～放。～配。\n(8)品类，等级～辈。～派。\n(9)指不正派二～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-流"},{"id":"glyph-kai-6d45","script":"kai","character":"浅","reading":"qiǎn","description":"通践”。实行,实现\n麦田浅鬣寸许\n⒉\"浅\"另见qiǎn。\n⒈从面到底或从外到里的距离小，跟\"深\"相对～井∮水～。巷道～。\n⒉不久，时间短年代～。结识的日子尚～。\n⒊程度不深，简明易懂～见。阅历～。学识～。功夫～。交情～。深入～出。\n⒋颜色淡～黄。～蓝。\n浅jiàn 1.灭，没。 2.通\"践\"。灭除;践踏。 3.通\"諓\"。参见\"浅浅\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浅"},{"id":"glyph-kai-6d46","script":"kai","character":"浆","reading":"jiāng","description":"古代一种微酸的饮料\n浓厚的液体\n用粉浆或米汤浸纱、布、衣服,使干后变硬变挺\n⒈较浓的液汁血～。绿豆～。泥灰～。\n⒉〈古〉一种带酸味的饮料，用以代酒。〈引〉酒玉液琼～。\n⒊用米汤或粉浆等浸透纱、布、衣服等物，使变硬变挺～布料。\n⒋见jiàng。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浆"},{"id":"glyph-kai-6d47","script":"kai","character":"浇","reading":"jiāo","description":"饮酒\n淋;洒\n浇铸\n⒈灌溉～花。～菜地。\n⒉把液体倒入模子里～钢板。\n⒊淋～水洗头发。\n⒋刻薄，不厚道～薄。\n浇nào 1.急流回旋貌。 2.指湍流扬起波浪。 3.通\"挠\"。参见\"浇滑\"。\n浇xiāo 1.方言〓南长沙等地呼布帛薄而不坚为浇。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浇"},{"id":"glyph-kai-6d4a","script":"kai","character":"浊","reading":"zhuó","description":"源出山东省益都县西南,北流注入小清河\n液体浑浊。与清”相对\n脏,不干净","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浊"},{"id":"glyph-kai-6d4b","script":"kai","character":"测","reading":"cè","description":"度量;测量\n观测,观察\n②测度观～。\n【测交】〈生〉最早由孟德尔设计的一种实验方法。是用杂种或杂种后代与纯合型隐性亲本交配，用以测定杂种或杂种后代基因型。\n【测量学】研究在地球表面测定地面点的相互位置与高程、绘成各种地图或确定地球形状与大小的一门科学。包括大地测量学、地形测量学、摄影测量学、工程测量学和海道测\n量学等。\n【测算】测量并计算。\n【测验赛】为达到一定的标准或了解运动员素质和水平提高情况而组织的竞赛。\n【测字】将汉字的偏旁部首拆开或合并，作出各种解说来推算凶吉。是一种迷信做法。又叫拆字。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-测"},{"id":"glyph-kai-6d4e","script":"kai","character":"济","reading":"jì","description":"发源于今河南省济源县西王屋山,原在山东境内与黄河并行入渤海◇因黄河改道,下游被黄河淹没。现在黄河下游的河道就是原来济水的河道\n州名\n五代周置,在今山东省巨野县\n金置,在今吉林省农安县\n众多\n⒈济水，〈古〉水名。发源于河南省，流经山东省入渤海。今黄河下流河道即原济水河道。\n⒉济南市，济宁市，均在山东省。\n⒈渡，过河同船～水。同舟共～。\n⒉帮助，援救接～。救～。～穷扶贫。\n⒊有利，补益万民以～。\n⒋成夫～大事必以人为本。\n济qí 1.庄敬。 2.整治，使整齐。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-济"},{"id":"glyph-kai-6d4f","script":"kai","character":"浏","reading":"liú","description":"通漻”。水深而清澈\n风疾速的样子\n风轻吹的样子\n⒈水流清亮的样子。\n⒉风刮得紧的样子。\n浏liū 1.溜。偷偷地走开。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浏"},{"id":"glyph-kai-6d51","script":"kai","character":"浑","reading":"hún","description":"河名\n桑干河上游支流,亦名浑源川,发源于山西省北端西麓\n卢沟河在元明后的别称,因河水浑浊得名,即今永定河\n小辽河,辽河最大的支流\n浑江,又名佟家江,发源于吉林省龙岗山脉\n中国古代少数民族吐谷浑的省称\n浑天说的简称\n⒈污浊，水不清～浊。～水。\n⒉糊涂～人。他讲的是～话。\n⒊全。满～身是胆。\n⒋天然的璞玉～金。\n浑hùn 1.混杂;混淆。 2.蒙混。 3.胡乱。 4.苟且度过;苟且获取。 5.逗趣的，开玩笑的。\n浑gǔn 1.见\"浑浑\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浑"},{"id":"glyph-kai-6d53","script":"kai","character":"浓","reading":"nóng","description":"稠密;厚;多\n特指液体或气体中所含某种成分多。与淡”、薄”相对\n⒈含某种成分多，跟\"淡\"相对～茶。～墨。\n⒉深厚，不淡薄～厚。～眉。兴趣很～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浓"},{"id":"glyph-kai-6d59","script":"kai","character":"浙","reading":"zhè","description":"zhè：〔～江〕ａ．古水名，今中国钱塘江及其上流的总称。亦称渐江”、之江”、曲江”；ｂ．省名，位于中国东部。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浙"},{"id":"glyph-kai-6d66","script":"kai","character":"浦","reading":"pǔ","description":"pǔ：(1)水边或河流入海的地区。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浦"},{"id":"glyph-kai-6d69","script":"kai","character":"浩","reading":"hào","description":"hào：水大，引申为大和多～大。～繁。～荡。～瀚。～劫。～淼（亦作浩渺”）。～气（盛大刚直之气）。～如烟海。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浩"},{"id":"glyph-kai-6d6a","script":"kai","character":"浪","reading":"làng","description":"làng：(1)大波波～。～。巨～。风～。～涛。～潮（亦喻大规模的社会运动）。风平～静。\n(2)像波浪起伏的麦～。声～。\n(3)没有约束，放纵放～。流～。～费。～迹。～人。孟～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浪"},{"id":"glyph-kai-6d6e","script":"kai","character":"浮","reading":"fú","description":"fú：(1)漂在水面上，与沉”相对～桥。～力。～标。～萍。～泛。～沉。漂～。～光掠影。\n(2)表面的～皮儿。～土。～雕。\n(3)空虚，不切实～夸。～华。\n(4)不沉静，不沉着轻～。～躁。\n(5)暂时的～记。～支。\n(6)可移动的～财。～荡。～吊。～动。\n(7)超过，多余人～于事。\n(8)呈现，涌现～现。～想。\n(9)中医指脉搏浮在肌肤表层～脉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浮"},{"id":"glyph-kai-6d74","script":"kai","character":"浴","reading":"yù","description":"yù：洗身，洗澡沐～。～室。～场。～缸。～巾。～血（全身浸于血中，形容战斗激烈）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浴"},{"id":"glyph-kai-6d77","script":"kai","character":"海","reading":"hǎi","description":"广阔的咸水水域。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-kai-6d78","script":"kai","character":"浸","reading":"jìn","description":"jìn：(1)泡，使渗透～泡。～透。～种（zhǒng）。～渍。～没（mò）。沉～（亦称浸沉”）。\n(2)逐渐～染。～渐。～润。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浸"},{"id":"glyph-kai-6d82","script":"kai","character":"涂","reading":"tú","description":"古水名。即今云南省之牛栏江。发源于寻甸,北流至威宁折向西北,至鲁甸县注入金沙江\n洞涡水支流。在山西省榆次县境\n道路。也作途”\n⒈抹刷，粉饰～抹。～刷。～饰。～油漆。\n⒉抹去～掉。～改。\n⒊乱写，乱画～鸦。不要乱～。\n⒌通\"途\"。道路。\n涂dù 1.以金饰物◇作\"镀\"。\n涂chú 1.通\"除\"。扫除。 2.古月名。称十二月。参见\"涂月\"。 3.古水名。即今安徽省合肥市东北之滁河，至江苏省六合县东南流入长江。\n涂yé 1.见\"涿涂山\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涂"},{"id":"glyph-kai-6d88","script":"kai","character":"消","reading":"xiāo","description":"xiāo：(1)溶化，散失烟～云散。～融（亦作消溶”）。～失。～逝。～亡。～沉。～极。～化。\n(2)灭掉，除去～除。～灭。～毒。～炎。\n(3)把时间度过去～夜。～夏。～闲。～遣。～磨（mó）。\n(4)减少，损失，耗费～耗。～损。～退。\n(5)需要不～说。\n(6)中医学病名～疾。～渴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-消"},{"id":"glyph-kai-6d89","script":"kai","character":"涉","reading":"shè","description":"shè：(1)步行过水～渡。～江。跋～。\n(2)到，经历～世（经历世事）。～历。～险。～足。\n(3)牵连，关连～及。～嫌。～外（涉及与外国关系的）。交～。牵～。～猎。\n(4)动，着（zhuó）～笔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涉"},{"id":"glyph-kai-6d8c","script":"kai","character":"涌","reading":"yǒng；chōng","description":"yǒng：(1)水由下向上冒出来～泉。～流。汹～。泪如泉～。\n(2)像水涌出～现。～动。风起云～。天边～出一轮明月。\nchōng：方言，河汊。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涌"},{"id":"glyph-kai-6d95","script":"kai","character":"涕","reading":"tì","description":"tì：(1)眼泪痛哭流～。感激～零。～泣。\n(2)鼻子里分泌的液体鼻～。～泪（鼻涕和眼泪）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涕"},{"id":"glyph-kai-6d9b","script":"kai","character":"涛","reading":"tāo","description":"像波涛一样的声音\n⒈大波浪波～。\n⒉像波涛的声音松～。\n涛cháo 1.潮汐。\n涛dào 1.覆盖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涛"},{"id":"glyph-kai-6d9d","script":"kai","character":"涝","reading":"lào","description":"又名潦水。在陕西省户县、周至两县界上,源出秦岭,为关中八川之一\n汾水支流。源出山西省浮山县西北,西流至临汾市北注入汾水\n水淹没;雨多成灾\n浇水,灌溉\n公今早晚班\n涝láo 1.水名。在今陕西省境内，为关中八川之一。 2.水名。在今山西省境内，源出浮山县黑山，西流合潏水，至临汾市北入汾水。 3.大波。 4.同\"捞\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涝"},{"id":"glyph-kai-6da1","script":"kai","character":"涡","reading":"wō；guo","description":"水名。今称涡河\n古州名\n小圆坑\n酒窝,嘴角附近的屑陷\n涡流\n⒈涡河，发源于河南省，流到安徽省入淮河。\n⒉见wō。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涡"},{"id":"glyph-kai-6da3","script":"kai","character":"涣","reading":"huàn","description":"huàn：散开～散。～然冰释（像冰遇到热，一下子消融；喻疑虑、困难或误会完全消除）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涣"},{"id":"glyph-kai-6da4","script":"kai","character":"涤","reading":"dí","description":"除,清除\n打扫\n涤宫,古代宫中饲养祭祀牲畜的房子\n涤 dí洗～除、洗～。\n【涤荡】同'荡涤'。洗涤；清除。\n【涤纶】一种合成纤维。用乙二醇、对苯二甲酸二甲酯等原料合成。\n【涤罪所】见【炼狱】。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涤"},{"id":"glyph-kai-6da6","script":"kai","character":"润","reading":"rùn","description":"修饰,使有光彩\n⒈潮湿，不干枯湿～。滋～。雨～万物。\n⒉加油或水，使不干燥～肤膏。～嗓子。\n⒊细腻，光滑丰～。光～。\n⒋修饰，使有光彩～饰。～色。\n⒌利益利～。分～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-润"},{"id":"glyph-kai-6da7","script":"kai","character":"涧","reading":"jiàn","description":"涧谷,山谷\n古代数词。万万沟为涧,即1064\n水名\n一曰涧水,出宏农西安东南入洛。╠","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涧"},{"id":"glyph-kai-6da8","script":"kai","character":"涨","reading":"zhǎng","description":"增长;高出\n大水貌\n⒈水量增大，水面高起来河水暴～。水～船高。\n⒉增高，特指物价提高～沙埋草。惩治乱～价。\n⒈体积增大～大。黄豆泡～了。\n⒉弥漫，充满烟尘～天。脸～得绯红。\n⒊多出来～出五元钱。\n涨zhāng 1.涨海。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涨"},{"id":"glyph-kai-6da9","script":"kai","character":"涩","reading":"sè","description":"味不甘滑\n⒈使舌头感到不滑润、不好受的一种滋味这柿子～口。\n⒉不光滑，不滑溜滞～。枯～。\n⒊文章难读难懂文字生～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涩"},{"id":"glyph-kai-6dae","script":"kai","character":"涮","reading":"shuàn","description":"shuàn：(1)摇动着冲刷，略微洗洗～瓶子。\n(2)把肉片等放在滚水里烫一下就取出来蘸作料吃～羊肉。～锅子。\n(3)耍弄，骗别～我啦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涮"},{"id":"glyph-kai-6daf","script":"kai","character":"涯","reading":"yá","description":"yá：(1)水边，泛指边际～～。～际。～岸。～垠。生也有～，而知也无～。”\n(2)范围，限度生～。～分（fèn）（限度，本分）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涯"},{"id":"glyph-kai-6db2","script":"kai","character":"液","reading":"yè","description":"yè：(1)能流动、有一定体积而没有一定形状的物质～体。～汁。～晶。～态。血～。精～。溶～。津～。\n(2)澄清凡为弓，冬析干而春～角”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-液"},{"id":"glyph-kai-6db5","script":"kai","character":"涵","reading":"hán","description":"hán：(1)包容，包含～蓄。～容。～养（ａ．蓄积并保持，如～～水源”；ｂ．指修养，如他很有～～”）。包～。蕴～。～。\n(2)沉，潜～泳（水中潜行，喻深入体会）。～淹。～濡（浸渍，滋润）。\n(3)公路或铁路下面通沟渠的管道～洞。桥～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涵"},{"id":"glyph-kai-6dc0","script":"kai","character":"淀","reading":"diàn","description":"蓝靛。一种蓝色染料\n淤积\n沉淀\n①浅的湖泊白洋～。\n②液体中沉下去的东西～粉。\n马铃薯的块茎中，是主要的碳水化合物食品，用于烹调菜肴，工业上用来制酒精、糖等。直链结构的淀粉遇碘呈蓝色。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淀"},{"id":"glyph-kai-6dc6","script":"kai","character":"淆","reading":"xiáo","description":"xiáo：混乱，错杂～乱。混～。～惑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淆"},{"id":"glyph-kai-6dcb","script":"kai","character":"淋","reading":"lín；lìn","description":"lín：浇～浴。～湿。日晒雨～。\n〔～漓〕ａ．沾湿或流滴，如大汗～～”；ｂ．畅快，如～～尽致。”\nlìn：(1)过滤过～。\n(2)一种性病，病原体是淋病球菌。病人尿道红肿溃烂，尿有浓血。通称淋病”；亦称白浊”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淋"},{"id":"glyph-kai-6dcc","script":"kai","character":"淌","reading":"tǎng；chǎng","description":"tǎng：流下～水。～汗。～眼泪。\n流；\nchǎng：水起波纹～游（水流动泛起波纹的样子）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淌"},{"id":"glyph-kai-6dd1","script":"kai","character":"淑","reading":"shū","description":"shū：(1)善，美（多指女性）～质（善良的品质）。～丽。～静。～慎。～德。～女。\n(2)清澈～清。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淑"},{"id":"glyph-kai-6dd8","script":"kai","character":"淘","reading":"táo","description":"táo：(1)用水洗去杂质～米。～金。～汰。\n(2)挖浚，从深处舀出泥沙、污物～井。～缸。\n(3)耗费～神。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淘"},{"id":"glyph-kai-6de1","script":"kai","character":"淡","reading":"dàn","description":"dàn：(1)含盐分少，与咸”相对味～。～水。～化。\n(2)浅，薄，含某种成分少，与浓”相对～酒。～绿。～薄。浅～。～雅。天高云～。\n(3)不热心冷～。～泊（对名利不热心）。～漠。～忘。恬～。\n(4)营业不旺盛～季。\n(5)无关紧要，无聊扯～。～话。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淡"},{"id":"glyph-kai-6de4","script":"kai","character":"淤","reading":"yū","description":"yū：(1)水道被泥沙阻塞～塞。～积。～滞。～埋。\n(2)河沟中沉积的泥沙～泥。～溉。\n(3)同瘀”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淤"},{"id":"glyph-kai-6deb","script":"kai","character":"淫","reading":"yín","description":"yín：(1)过多，过甚～辞。～雨。～威。\n(2)渐浸，浸渍浸～。\n(3)迷惑富贵不能～。\n(4)在男女关系上态度或行为不正当奸～。～荡。～乱。～秽。～猥。～书。\n(5)放纵，沉溺～湎（沉溺于酒）。骄奢～逸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淫"},{"id":"glyph-kai-6dee","script":"kai","character":"淮","reading":"huái","description":"huái：〔～河〕水名，源于中国河南省桐柏山，流经安徽、江苏两省入洪泽湖。简称淮”，如～北”。～南”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淮"},{"id":"glyph-kai-6df1","script":"kai","character":"深","reading":"shēn","description":"shēn：(1)从表面到底或从外面到里面距离大，与浅”相对～水。～山。～邃。～渊。～壑。～海。～耕。～呼吸。～藏若虚（把珍贵的东西深藏起来，好像没有一样，喻人有知识才能但不在人前表现）。～居简出。\n(2)从表面到底的距离～度。～浅。。水～三尺。\n(3)久，时间长～夜。～秋。年～日久。\n(4)程度高的～思。～知。～交。～造。～谈。～省（xǐng）（深刻的警悟。亦作深醒”）。～究。～奥。～切。～沉（ａ．形容程度深，如暮色～～”；ｂ．声音低沉，如～～的哀鸣”；ｃ．思想感情不外露，如他为人～～，叫人难以捉摸”）。～谋远虑。\n(5)颜色浓～色。～红。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-深"},{"id":"glyph-kai-6df3","script":"kai","character":"淳","reading":"chún；zhūn","description":"chún：(1)朴实～朴。～厚。～古。～风（质朴敦厚的风气）。\n(2)成对。\n(3)古同醇”，酒味厚、纯。\nzhūn：浇灌～而渍之”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淳"},{"id":"glyph-kai-6df7","script":"kai","character":"混","reading":"hùn；hún","description":"hùn：(1)搀杂在一起～杂。～和。～同。～淆。～为一谈。\n(2)乱，胡乱～乱。～世魔王。\n(3)蒙，充蒙～。～充。～进。鱼目～珠。\n(4)苟且度过胡～。～事。\nhún：同浑”①②。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-混"},{"id":"glyph-kai-6df9","script":"kai","character":"淹","reading":"yān","description":"yān：(1)浸没（mò）水～。～没（mò）。～灌。\n(2)皮肤被汗液浸渍胳肢窝被汗～得又痛又痒。\n(3)广～博。～通。～贯（渊博而贯通）。～雅（渊博高雅）。\n(4)滞，久留～留。久～。～滞。～月（滞留一月）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淹"},{"id":"glyph-kai-6dfb","script":"kai","character":"添","reading":"tiān","description":"tiān：增加增～。～设。～补。锦上～花。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-添"},{"id":"glyph-kai-6e05","script":"kai","character":"清","reading":"qīng","description":"清澈、洁净，也可形容清静。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-kai-6e0a","script":"kai","character":"渊","reading":"yuān","description":"深潭\n⒈深水，潭深～。鱼跃于～。\n⒉深，深远学识～博。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渊"},{"id":"glyph-kai-6e10","script":"kai","character":"渐","reading":"jiàn","description":"流入;入\n淹没,浸泡\n熏染,可染\n⒈浸～渍。～染。\n⒉慢慢流入东～于海。〈引〉疏导禹功之大，～九川。\n⒉事物的开端防微杜～。\n渐qián 1.潜伏。\n渐chán 1.山石高峻貌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渐"},{"id":"glyph-kai-6e14","script":"kai","character":"渔","reading":"yú","description":"掠夺\n①捕鱼。\n②捕鱼的人。\n③侵占，掠夺。\n④泛指寻觅。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渔"},{"id":"glyph-kai-6e17","script":"kai","character":"渗","reading":"shèn","description":"水枯竭\n其他事物渐\n渗sēn 1.见\"淋渗\"。\n渗qīn 1.见\"渗淫\"。\n渗lín 1.见\"渗漓\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渗"},{"id":"glyph-kai-6e1d","script":"kai","character":"渝","reading":"yú","description":"yú：(1)改变，违背（多指感情或态度）忠贞不～。生死不～。\n(2)中国四川省重庆市的别称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渝"},{"id":"glyph-kai-6e20","script":"kai","character":"渠","reading":"qú；jù","description":"qú：(1)水道，特指人工开的河道或水沟～道（亦指途径，门路）。沟～。\n(2)大～帅。～魁（首领）。\n(3)方言，他～侬（他，他们）。～辈。\n(4)车辋，古代车轮的外圈。\njù：岂掾部～有其人乎？”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渠"},{"id":"glyph-kai-6e21","script":"kai","character":"渡","reading":"dù","description":"dù：(1)横过水面～船。～桥。～河。摆～。强～。远～重洋。\n(2)由此到彼～过难关。\n(3)转手，移交引～。\n(4)过河的地方～口。～头。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渡"},{"id":"glyph-kai-6e23","script":"kai","character":"渣","reading":"zhā","description":"zhā：(1)提出精华或汁流后剩的东西～子。～滓。豆腐～。\n(2)碎屑干粮～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渣"},{"id":"glyph-kai-6e24","script":"kai","character":"渤","reading":"bó","description":"bó：〔～海〕在中国山东半岛与辽东半岛之间的海。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渤"},{"id":"glyph-kai-6e29","script":"kai","character":"温","reading":"wēn","description":"wēn：(1)不冷不热～带。保～。降～。～泉。～和。～床。\n(2)性情柔和～柔。～存（抚慰体贴）。～情。～顺。～静。～良。～文尔雅。\n(3)稍微加热把酒～一下。\n(4)复习～习。～故而知新。\n(5)古同瘟”。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-温"},{"id":"glyph-kai-6e2f","script":"kai","character":"港","reading":"gǎng；jiǎng","description":"gǎng：(1)江河的支流～汊。\n(2)可以停泊大船的江海口岸商～。军～。～口。～湾。～务。\n(3)指香港”～府。～币。～商。\njiǎng：方言，指山凹或山沟（多用于地名）前头～。上～。下～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-港"},{"id":"glyph-kai-6e32","script":"kai","character":"渲","reading":"xuàn","description":"xuàn：把水、墨淋在纸上再擦匀的画法～染（ａ．中国画技法之一，用水墨或淡的色彩烘涂画面，以加强艺术效果；ｂ．喻夸大地形容；ｃ．文艺作品中通过多方面的描写、形容或烘托来突出形象）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渲"},{"id":"glyph-kai-6e34","script":"kai","character":"渴","reading":"kě","description":"kě：(1)口干想喝水口～。解～。\n(2)喻迫切地～望。～盼。～慕。～求。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渴"},{"id":"glyph-kai-6e38","script":"kai","character":"游","reading":"yóu","description":"yóu：(1)人或动物在水里行动～泳。～水。\n(2)不固定～资。～走。～牧。～行。～学（古指离开本乡到外地或外国求学）。～击。～弋。～离。～子（离家久居外乡的人）。\n(3)河流的一段上～。中～。下～。\n(4)交往，来往交～。\n(5)从容地行走周～。～历。～逛。～兴（xìng）。～记。～说（shuì）。～山玩水。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-游"},{"id":"glyph-kai-6e3a","script":"kai","character":"渺","reading":"miǎo","description":"miǎo：(1)微小～小。～不足道。\n(2)水势辽远浩～。～邈。～～。～然。\n(3)茫茫然，看不清楚～茫。～无人迹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渺"},{"id":"glyph-kai-6e43","script":"kai","character":"湃","reading":"pai；pài","description":"pài：〔澎～〕见澎”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湃"},{"id":"glyph-kai-6e56","script":"kai","character":"湖","reading":"hú","description":"hú：(1)陆地上聚积的大水～泊。～泽。～滩。～荡。～光山色。\n(2)指中国湖北省和湖南省两～。～广。\n(3)指中国湖州（旧地名，在今浙江省吴兴县）～笔。～绉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湖"},{"id":"glyph-kai-6e58","script":"kai","character":"湘","reading":"xiāng","description":"xiāng：湖南省的别称～绣。～剧。～菜。～语。\n〔～江〕水名，源出中国广西壮族自治区，经过湖南省，注入洞庭湖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湘"},{"id":"glyph-kai-6e7e","script":"kai","character":"湾","reading":"wān","description":"海湾\n村庄\n系泊,在水湾处停泊\n用于水或水面,相当于处\n⒈水流弯曲的地方河～。\n⒉海洋向陆地凹入的地方港～。渤海～。\n⒊使船停住将船～在这儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湾"},{"id":"glyph-kai-6e7f","script":"kai","character":"湿","reading":"shī","description":"湿tà 1.古水名。\n湿xí 1.通\"隰\"。 2.通\"?\"。低下。\n湿xiè 1.古人名用字。\n湿chì 1.见\"湿湿\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湿"},{"id":"glyph-kai-6e83","script":"kai","character":"溃","reading":"kuì","description":"⒈水冲破堤坝～决。～溢。大水～出。〈引〉冲破包围～围而出。\n⒉散乱，垮台～散。败将～兵。～不成军。经济崩～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溃"},{"id":"glyph-kai-6e85","script":"kai","character":"溅","reading":"jiàn","description":"溪谷溅溅\n黄河流水鸣溅溅\n液体受到冲激向四外飞射\n溅落\n重物自高处落入水中\n指人造卫星、宇宙飞船等返回地球时,\n⒉\"溅\"另见jiàn。\n⒈液体受冲激向周围飞射水花四～。　～了一身稀泥。\n⒉见jiān。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溅"},{"id":"glyph-kai-6e89","script":"kai","character":"溉","reading":"gài","description":"gài：(1)浇灌灌～。\n(2)洗涤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溉"},{"id":"glyph-kai-6e90","script":"kai","character":"源","reading":"yuán","description":"yuán：(1)水流所从出的地方河～。泉～。发～。～远流长。～头。\n(2)事物的根由来～。资～。渊～。能～。起～。策～地。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-源"},{"id":"glyph-kai-6e9c","script":"kai","character":"溜","reading":"liū；liù","description":"liū：(1)滑行，（往下）滑～冰。\n(2)光滑，平滑，无阻碍～圆。～光。\n(3)趁人不见走开～走。～号。\n(4)同熘”。\nliù：(1)迅急的水流大～。急～。\n(2)顺房檐滴下来的水，房顶上流下的水檐～。承～。\n(3)房檐上安的接雨水用的长水槽水～。\n(4)量词，指行（háng）列，排一～三间房。\n(5)某一地点附近的地方这～儿的果木树很多。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溜"},{"id":"glyph-kai-6ea2","script":"kai","character":"溢","reading":"yì","description":"yì：(1)充满而流出来～流∮水四～。洋～。充～。～于言表。\n(2)过分～美。～恶。～誉。\n(3)超出～出此数。\n(4)古同镒”，古代重量单位。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溢"},{"id":"glyph-kai-6eaa","script":"kai","character":"溪","reading":"xī","description":"xī：山里的小河沟，泛指小河沟山～。清～。～水。～涧。～谷。～壑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溪"},{"id":"glyph-kai-6eaf","script":"kai","character":"溯","reading":"sù","description":"sù：(1)逆着水流的方向走～流而上。\n(2)追求根源或回想回～。追～。上～。追本～源。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溯"},{"id":"glyph-kai-6eb6","script":"kai","character":"溶","reading":"róng","description":"róng：在水中或其他液体中化开～化。～解。～液。～剂。～洞。\n〔～～〕ａ．形容宽广；ｂ．形容水流动；ｃ．形容月色荡漾。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溶"},{"id":"glyph-kai-6eba","script":"kai","character":"溺","reading":"nì；niào","description":"nì：(1)淹没～水。～死。\n(2)沉迷不悟，过分，无节制～爱。沉～。\nniào：同尿1”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溺"},{"id":"glyph-kai-6ec7","script":"kai","character":"滇","reading":"diān","description":"diān：(1)古族名，在今中国云南省东部滇池附近地区。\n(2)中国云南省的别称～红（云南出产的红茶）。～剧。～池。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滇"},{"id":"glyph-kai-6ecb","script":"kai","character":"滋","reading":"zī","description":"zī：(1)生出，长～生。～芽。～事。～扰（骚扰生事）。潜～暗长。\n(2)增益，加多～养。～补。～阴。\n(3)汁液，润泽～润。\n(4)味道～味。\n(5)喷射往外～水。\n(6)浊何故使吾水～？”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滋"},{"id":"glyph-kai-6ed1","script":"kai","character":"滑","reading":"huá","description":"huá：(1)光溜，不粗涩～溜。光～。～润。～利。\n(2)在光溜的物体表面上溜动～冰。～雪。～行。～翔。～梯。～坡。\n(3)狡诈，不诚实～头。狡～。～头～脑。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滑"},{"id":"glyph-kai-6ed4","script":"kai","character":"滔","reading":"tāo","description":"tāo：(1)弥漫，充满～天。～～。\n(2)倨慢士不滥，官不～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滔"},{"id":"glyph-kai-6eda","script":"kai","character":"滚","reading":"gǔn","description":"gǔn：(1)水流翻腾大江～～东去。\n(2)形容急速地翻腾风烟～～。\n(3)水煮开，沸腾～沸。～开。\n(4)旋转着移动～动。翻～◇～翻。～筒。～珠。～雪球。\n(5)走开，离开（含斥责意）～出去！\n(6)一种缝纫方法，沿着衣服等的边缘缝上布条、带子等～边。\n(7)很，极，特别～烫。～圆。～瓜流油。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滚"},{"id":"glyph-kai-6ede","script":"kai","character":"滞","reading":"zhì","description":"积压。长期积存,未作处理\n停止;阻塞;静止\n滞chì 1.见\"滞沛\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滞"},{"id":"glyph-kai-6ee1","script":"kai","character":"满","reading":"mǎn","description":"⒈全～分。～身是泥。\n⒉足，够，符合心意～足。心～意足。非常～意。\n⒊充实，没有余地充～。布～。粮食～仓。\n⒋达到一定限度客～。假期将～。\n⒌骄傲，不虚心自～。谦受益，～遭损。\n⒍斟酒，使满～上这杯。\n满mèn 1.通\"懑\"。烦闷。 2.中医学名词。胀满;壅滞。 3.用同\"们\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-满"},{"id":"glyph-kai-6ee4","script":"kai","character":"滤","reading":"lǜ","description":"滤（瀡）lǜ使液体、气体通过布、纸、沙等，除去其中的杂质、毒气等过～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滤"},{"id":"glyph-kai-6ee5","script":"kai","character":"滥","reading":"làn","description":"大水漫出,泛滥\n浸渍,泡在水里\n⒈大水漫溢泛～成灾。〈引〉过度，无节制～用职权。\n⒉失真，不切实际采～忽真。～竽充数。陈词～调。\n滥jiàn 1.泉水涌出貌。参见\"滥泉\"。 2.古水名。\n滥lǎn 1.以干果浸渍于水中作成的饮料。 2.谓以盐等腌渍食物。 3.揽聚。\n滥lán 1.春秋邾邑名，在今山东省滕县﹑枣庄市之间。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滥"},{"id":"glyph-kai-6ee8","script":"kai","character":"滨","reading":"bīn","description":"湖、河、海的水边陆地\n古州名\n通濒”。靠近;临近\n①水边；近水的地方东海之～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滨"},{"id":"glyph-kai-6ee9","script":"kai","character":"滩","reading":"tān","description":"滩头。指江、河、湖、海边水涨淹没、水退显露的淤积平地\n等级\n这种奴隶叫作三滩娃子”。滩是等级的意思。管家娃子为头滩,普通娃子为\n⒈江、河或海边泥沙淤积的平地。也指水中的沙洲河～。～。沙～。\n⒉水浅、多石、流急的地方险～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滩"},{"id":"glyph-kai-6ef4","script":"kai","character":"滴","reading":"dī","description":"dī：(1)液体一点一点地向下落～眼药。～落。～翠。水～石穿（喻只要有恒心，不断努力，事情一定能成功，亦作滴水穿石”）。～漏（漏壶）。\n(2)一点一点向下落的液体水～」～。\n(3)量词，用于滴下的液体的数量～水不漏。两～墨水。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滴"},{"id":"glyph-kai-6f02","script":"kai","character":"漂","reading":"piāo；piǎo；piào","description":"piāo：浮在液体上不动或顺着风向、流向而移动～浮。～流。～没（mò）。～移。～泊（喻职业生活不固定，东奔西走。亦作飘泊”）。～零。～沦。～游。～萍。\npiǎo：(1)用水加药品使物品退去颜色或变白～白。～染。\n(2)用水冲去杂质～洗。\npiào：方言，事情、账目等落空那事没什么指望，～了。\n〔～亮〕ａ．好看，如长得～～”；ｂ．出色，如这件事办得～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漂"},{"id":"glyph-kai-6f06","script":"kai","character":"漆","reading":"qī","description":"qī：(1)落叶乔木，树皮内富含树脂，与空气接触后呈褐色，即生漆”，可制涂料，液汁干后可入药。\n(2)用漆树皮的黏汁或其他树脂做成的涂料油～。～片。～器；～雕；磨～画（均为工艺品）。～包线。\n(3)用漆涂把门窗～一下。\n(4)黑～黑一团（ａ．形容非弛暗，没有一点光明；ｂ．形容一无所知。均亦作一团漆黑”）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漆"},{"id":"glyph-kai-6f0f","script":"kai","character":"漏","reading":"lòu","description":"lòu：(1)物体由孔或缝透过壶里的水～光了。～风。渗～。～泄（ａ．水、光等流出或透出；ｂ．泄露）。～电（跑电）。\n(2)泄露走～消息。～底（泄露内情）。透～。\n(3)脱逃或无意放过疏～。遗～。挂一～万。～网之鱼。\n(4)中医指某些流出脓血黏液的病崩～（子宫大量出血的病）。痔～。\n〔～壶〕古代计时器，铜制有孔，可以滴水或漏沙，有刻度标志以计时间。简称漏”，如铜壶滴～”（亦称铜壶刻漏”），～尽更深”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漏"},{"id":"glyph-kai-6f13","script":"kai","character":"漓","reading":"lí","description":"浅薄;浇薄\n漓江\n⒉漓江，在广西壮族自治区。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漓"},{"id":"glyph-kai-6f14","script":"kai","character":"演","reading":"yǎn","description":"yǎn：(1)根据事理推广发挥推～。讲～（亦作演讲”）。～义（以史书及传说的材料为基础，增添一些细节，用章回体写成的小说）。～绎（一种推理方法，由一般原理推出关于特殊情况下的结论）。\n(2)依照程式练习～练。～示。～算。～武。～习。～兵场。\n(3)不断变化～变。～化。\n(4)把技艺当众表现出来表～。～出。～播。～奏。主～。义～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-演"},{"id":"glyph-kai-6f20","script":"kai","character":"漠","reading":"mò","description":"mò：(1)面积阔大无人定居，缺水干燥的沙石地带沙～。～北。\n(2)空旷广～。荒～。～～。\n(3)冷淡地，不经心地～视。～不关心。\n(4)古同寞”，寂静无声。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漠"},{"id":"glyph-kai-6f2b","script":"kai","character":"漫","reading":"màn","description":"màn：(1)水过满，四外流出，漾出来河水～出河床。～溢。～流。～漶（文字、图画等因受潮而凝不清，如字迹～～”）。\n(2)淹没大水～过桥面。\n(3)满，遍，到处都是迷～。～山遍野。\n(4)没有限制，没有约束，随意散～。～谈。～话。～步。～不经心。～骂（乱骂）。～～（时间或空间没有边际，如～～长夜”）。～游。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漫"},{"id":"glyph-kai-6f31","script":"kai","character":"漱","reading":"shù","description":"shù：含水荡洗口腔～口。洗～。盥～（洗手或漱口）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漱"},{"id":"glyph-kai-6f3e","script":"kai","character":"漾","reading":"yàng","description":"yàng：(1)水面动荡荡～。\n(2)液体溢出来～奶。\n(3)方言，小的湖泊。\n〔～濞（bì）〕ａ．水名，在中国云南省，澜沧江支流；ｂ．地名，在中国云南省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漾"},{"id":"glyph-kai-6f47","script":"kai","character":"潇","reading":"xiāo","description":"急疾\n水名。潇水\n⒈水清且深。\n⒉风雨声风雨～ ～。\n⒋潇水，在湖南省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潇"},{"id":"glyph-kai-6f58","script":"kai","character":"潘","reading":"pān","description":"pān：(1)淘米汁。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潘"},{"id":"glyph-kai-6f5c","script":"kai","character":"潜","reading":"qián","description":"qián：(1)隐在水面下活动～水。～泳。～坝。～行（ａ．在水面以下行动；ｂ．在外边秘密行动）。\n(2)隐藏的，秘密地～藏。～伏。～遁。～逃。～力。～心。～师。～在。～台词。～移默化。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潜"},{"id":"glyph-kai-6f6d","script":"kai","character":"潭","reading":"tán","description":"tán：(1)水深之处深～。泥～。水～。\n(2)深～渊。～～（宽深，宽大）。～思（深思。亦作覃思”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潭"},{"id":"glyph-kai-6f6e","script":"kai","character":"潮","reading":"cháo","description":"cháo：(1)海水因为受了日月的引力而定时涨落的现象～水。～汐。涨～。落～。～汛。～流。～涌。\n(2)像潮水那样汹涌起伏的思～。热～。新～。～红。～热。心～澎湃。\n(3)湿～气。返～。～湿。\n(4)方言，技术不高手艺～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潮"},{"id":"glyph-kai-6f84","script":"kai","character":"澄","reading":"chéng；dèng","description":"chéng：水静而清～莹。～酒（淡酒）。～汰。～澈。～湛。～廓。～清。～碧。～净。～静。～明。\ndèng：让液体里的杂质沉下去～清。～沙。～泥浆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-澄"},{"id":"glyph-kai-6f88","script":"kai","character":"澈","reading":"chè","description":"chè：(1)水清清～。澄～。～底。\n(2)同彻”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-澈"},{"id":"glyph-kai-6f8e","script":"kai","character":"澎","reading":"péng","description":"péng：溅～了一身水。\n〔～湃〕ａ．形容波涛撞击，如奔腾～～”；ｂ．喻声势浩大，气势雄伟，如热情～～的诗篇”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-澎"},{"id":"glyph-kai-6f9c","script":"kai","character":"澜","reading":"lán","description":"波纹\n澜lán大波浪狂～。推波助～。\n澜làn 1.见\"澜漫\"。 2.见\"澜贱\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-澜"},{"id":"glyph-kai-6fa1","script":"kai","character":"澡","reading":"zǎo","description":"zǎo：沐浴全身，引申为保持节操洗～。～盆。～堂。～雪（洗涤使清洁）。～身浴德（砥砺志行，使身心纯洁清白）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-澡"},{"id":"glyph-kai-6fb3","script":"kai","character":"澳","reading":"ào","description":"ào：(1)海边弯曲可以停船的地方（多用于地名）～门（简称澳”）。\n(2)指澳大利亚洲”（大洋洲”的旧称，简称澳洲”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-澳"},{"id":"glyph-kai-6fc0","script":"kai","character":"激","reading":"jī","description":"jī：(1)水受阻遏，震荡而涌或飞溅冲～。～荡。～浊扬清（冲击污水，让清水上来，喻打击坏人坏事，奖励好人好事）。\n(2)冷水突然浇淋或冲、泡食物～酸菜。\n(3)鼓动，使人的感情冲动刺～。～励。\n(4)感情冲动感～。～动。～昂慷慨。\n(5)急剧的，强烈的～烈。～进。\n(6)过分直率～厉。～切。\n(7)鲜明唇如～丹。\n〔～光〕某些物质的原子中的粒子受光或电刺激，使低能级的原子变成高能级原子，而辐射出相位、频率、方向等完全相同的光，称激光”。亦称莱塞”、镭射”。\n〔～光器〕产生激光的装置。\n〔～素〕内分泌腺分泌的物质。亦称荷尔蒙”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-激"},{"id":"glyph-kai-6fd2","script":"kai","character":"濒","reading":"bīn","description":"靠近;临近\n濒 bīn接近南～长江、～临绝境。\n【濒临】紧接～太平洋、～崩溃。\n【濒危】接近危难。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-濒"},{"id":"glyph-kai-7011","script":"kai","character":"瀑","reading":"bào；pù","description":"pù：〔～布〕水从高山陡直地流下来，远看好像挂着的白布。简称瀑”，如飞～流泉”。\nbào：暴雨。\n〔～河〕水名，在中国河北省。亦作鲍河”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瀑"},{"id":"glyph-kai-704c","script":"kai","character":"灌","reading":"guàn","description":"guàn：(1)浇地～溉。～渠。浇～。\n(2)注入液体～注。～浆。～肠。\n(3)指录音～唱片。\n(4)炼铸。\n(5)丛生，亦指丛生的树木～木。～丛。\n(6)古代祭祀的一种仪式，斟酒浇地降神。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灌"},{"id":"glyph-kai-706b","script":"kai","character":"火","reading":"huǒ","description":"huǒ：(1)燃烧，物质燃烧时所发出的光和焰～力。～烛。～源。～焰。烟～。～中取栗（喻为别人冒险出力，而自己吃亏上当，毫无所获）。\n(2)紧急～速。十万～急。\n(3)指枪炮弹药等～药。～炮。\n(4)发怒，怒气～暴。～性。\n(5)中医指发炎、红肿、烦躁等的病因肝～。毒～攻心。\n(6)形容红色的～红。～腿。\n(7)古代军队组织，一火十个人。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-火"},{"id":"glyph-kai-706d","script":"kai","character":"灭","reading":"miè","description":"⒈熄，熄火～ 火。～灯。熄～。\n⒉使不存在～亡。消～。磨～。毁～。\n⒊淹没～顶。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灭"},{"id":"glyph-kai-706f","script":"kai","character":"灯","reading":"dēng","description":"彩灯。特指元宵节挂的彩灯\n灯 dēng照明或做其他用途的发光器具电～、探照～、无影～。\n【灯蛾扑火】比喻自寻死路，自取灭亡。又作飞蛾扑火、飞蛾赴火、飞蛾投火。\n【灯红酒绿】形容寻欢作乐、奢侈腐化的生活。又作酒绿灯红。\n【灯心绒】比一般布厚实的棉织品，布面上有像灯心草一样的绒条。'心'又作'芯'。又称条绒。\n【灯芯绒】参见【灯心绒】。\n【灯语】通讯方法之一，在夜间用灯光明灭间歇的长短显示出不同的信号。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灯"},{"id":"glyph-kai-7070","script":"kai","character":"灰","reading":"huī","description":"huī：(1)物体燃烧后剩下的东西，经烧制后形成的产品纸～。～烬。洋～。～飞烟灭。\n(2)尘土～尘。\n(3)特指石灰”～墙。～膏。\n(4)黑白之间的颜色～色。～质（脑和脊髓的灰色部分）。～沉沉。\n(5)志气消沉心～意懒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灰"},{"id":"glyph-kai-7075","script":"kai","character":"灵","reading":"líng","description":"古时楚人称跳舞降神的巫为灵\n神灵\n⒈有效验～验。～丹妙药。\n⒉聪明，机敏，敏捷～敏。～活。～机。心～手巧。\n⒊活动迅速，准确这部仪器很～。失～。\n⒋传说中或迷信者称\"神\"及\"关于神仙\"的神～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灵"},{"id":"glyph-kai-7076","script":"kai","character":"灶","reading":"zào","description":"烧炼或锻造的设备\n灶神","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灶"},{"id":"glyph-kai-7078","script":"kai","character":"灸","reading":"jiǔ","description":"jiǔ：烧，中医的一种医疗方法。用艾叶等制成艾炷或艾卷，烧灼或熏烤人身的穴位针～（针刺与艾灸的合称）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灸"},{"id":"glyph-kai-707c","script":"kai","character":"灼","reading":"zhuó","description":"zhuó：(1)烧，炙～热。～伤（烧伤）。焦～。心急如～。\n(2)明白透彻真知～见。\n(3)鲜明～～。～亮。～然。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灼"},{"id":"glyph-kai-707e","script":"kai","character":"灾","reading":"zāi","description":"zāi：(1)水、火、荒旱等所造成的祸害水～。火～。～难（nàn）。～害。～患。\n(2)个人的不幸遭遇招～惹祸。幸～乐祸。破财消～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灾"},{"id":"glyph-kai-707f","script":"kai","character":"灿","reading":"càn","description":"鲜艳;鲜明\n明白,清楚\n灿 cǎn灿烂】鲜明耀眼星光～。\n灿càn 1.明亮貌。 2.鲜艳貌;鲜明貌。 3.明白，清楚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灿"},{"id":"glyph-kai-7089","script":"kai","character":"炉","reading":"lú","description":"火炉\n炉上有壶。\n为炉,为壶。\n古代酒店前放置酒坛的土台\n⒈取暖、做饭、冶炼等用的供热器具手～。电磁～。煤气～子。炼钢～子。\n⒉\"鑪\"另见rfum。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炉"},{"id":"glyph-kai-708a","script":"kai","character":"炊","reading":"chuī","description":"chuī：烧火做饭～事。～烟。巧妇难为无米之～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炊"},{"id":"glyph-kai-708e","script":"kai","character":"炎","reading":"yán","description":"yán：(1)热～热。～凉（ａ．气候的热和冷；ｂ．喻人情势利，或亲热攀附，或冷漠疏远，反复无常）。趋～附势。～～（灼热；火炽盛；引申为兴盛，亦指威势显赫）。\n(2)身体的一部分发生红、肿、热、痛的现象～症。\n(3)传说中的中国上古帝王中的一位，并成为中华民族千百年的象征～帝。～黄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炎"},{"id":"glyph-kai-7092","script":"kai","character":"炒","reading":"chǎo","description":"chǎo：(1)把东西放在锅里搅拌着弄熟～菜。～米。～面。～冷饭（喻办事不讲效率，说话做事只是简单地重复过去，没有新的内容）。～鱿鱼（方言，因鱿鱼一炒就卷起来，因以借指卷铺盖，解雇。亦简作炒”）。\n(2)倒买倒卖～黄鱼（指倒买倒卖黄金）。～地皮。～买～卖（指对股票外汇的买卖）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炒"},{"id":"glyph-kai-7095","script":"kai","character":"炕","reading":"kàng","description":"kàng：(1)北方用砖、坯等砌成的睡觉的台，下面有洞，连通烟囱，可以烧火取暖～席。火～。土～。\n(2)烤把湿衣服放在火边～一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炕"},{"id":"glyph-kai-70ab","script":"kai","character":"炫","reading":"xuàn","description":"xuàn：(1)光明照耀光彩～目。\n(2)夸耀～耀。～鬻（夸耀卖弄）。～弄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炫"},{"id":"glyph-kai-70ac","script":"kai","character":"炬","reading":"jù；jv","description":"jù：火把火～。目光如～。付之一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炬"},{"id":"glyph-kai-70ad","script":"kai","character":"炭","reading":"tàn","description":"tàn：(1)把木材和空气隔绝，加高热烧成的一种黑色燃料木～。～素。～笔。～画。\n(2)像炭的东西山楂～。\n(3)煤石～。焦～。泥～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炭"},{"id":"glyph-kai-70ae","script":"kai","character":"炮","reading":"pào；páo；bāo","description":"páo：烧～炙。～烙（luò）。～制。\nbāo：(1)把物品放在器物上烘烤或焙把湿衣服搁在热炕上～干。\n(2)一种烹调方法，在旺火上急炒～羊肉。\npào：(1)重型武器的一类，有迫击炮、高射炮、火箭炮等～兵。～弹。\n(2)爆竹鞭～。花～。\n(3)爆破土石等在凿的眼内装进炸药后称炮”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炮"},{"id":"glyph-kai-70b8","script":"kai","character":"炸","reading":"zhà；zhá","description":"zhà：(1)突然破裂爆～。～药。～弹。～响。\n(2)用炸药或炸弹爆破轰～。\n(3)发怒他一听就～了。\nzhá：把食物放在煮沸的油中弄熟～酱。～糕。～鱼。油～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炸"},{"id":"glyph-kai-70b9","script":"kai","character":"点","reading":"diǎn","description":"细小的黑色斑痕\n小滴\n汉字笔画名\n数学名词。数学上表示小数的符号叫小数点,省称为点”。\n几何系统,尤指欧几里","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-点"},{"id":"glyph-kai-70bc","script":"kai","character":"炼","reading":"liàn","description":"修炼;锻炼;造就\n⒈用加热法制做～焦。～钢材。～乳制品。\n⒉用心琢磨～写字。～造句。～作文。\n炼làn 1.腐烂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炼"},{"id":"glyph-kai-70c1","script":"kai","character":"烁","reading":"shuò","description":"热;烫;烤灼\n摇曳;闪烁\n通铄”。销熔\n烁luò 1.见\"爆烁\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烁"},{"id":"glyph-kai-70c2","script":"kai","character":"烂","reading":"làn","description":"此儿头不烂。\n是必烂也。\n三首俱烂。\n火烧伤\n头绪乱\n零碎,断片\n⒈稀软～泥。\n⒉过熟，熟透蚕豆煮～了。〈引〉极，甚这本书读得～熟。\n⒊腐朽，败坏敌人一天天～下去。\n⒋腐坏，破碎腐～。～桃子。～衣服。破铜～铁。\n⒌头绪乱～摊子。\n⒍［烂漫］［烂熳］［烂缦］\n①色彩鲜艳，光彩四射云霞～漫。\n②坦率自然，毫无做作天真～漫。\n③散乱忽～漫而无成。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烂"},{"id":"glyph-kai-70c8","script":"kai","character":"烈","reading":"liè","description":"liè：(1)火势猛；引申为猛，厉害～火。～焰。～酒。～马。～性。激～。剧～。\n(2)气势盛大轰轰～～。\n(3)刚直，有高贵品格的；为正义而死难的～女。壮～。先～。～士。\n(4)功业功～。\n(5)古同列”，行列。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烈"},{"id":"glyph-kai-70d8","script":"kai","character":"烘","reading":"hōng","description":"hōng：(1)用火或蒸气使身体暖和或使物体变热、干燥～箱。～手。～干（gān）。～烤。～焙。\n(2)烧。\n(3)衬托，渲染～衬。～托。～染。～云托月（喻从侧面加以点染以烘托所描绘的事物）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烘"},{"id":"glyph-kai-70d9","script":"kai","character":"烙","reading":"lào；luò","description":"lào：(1)用器物烫熨～衣服。～印。～花（亦称烫花”）。\n(2)把面食放在烧热的铛或锅上加热使熟～饼。～锅贴。\nluò：〔炮（páo）～〕见炮1”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烙"},{"id":"glyph-kai-70db","script":"kai","character":"烛","reading":"zhú","description":"⒈以线绳或苇子做中心，周围用蜡和油脂包裹，点燃取光的东西蜡～成灰泪始干。\n⒉照见，照耀火光～天。〈引〉明察洞～其奸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烛"},{"id":"glyph-kai-70df","script":"kai","character":"烟","reading":"yān","description":"yān：(1)物质燃烧时所生的气体冒～。硝～。～囱。～雾。～波。～火。～尘。荒无人～。\n(2)像烟的～霞。～霭。～岚。～鬟。\n(3)烟气刺激使眼睛流泪或睁不开～了眼睛。\n(4)一年生草本植物～草。～叶。\n(5)烟草制成品香～。卷～。纸～。～蒂。\n(6)指鸦片”大～。～灯。～枪。～馆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烟"},{"id":"glyph-kai-70e4","script":"kai","character":"烤","reading":"kǎo","description":"kǎo：(1)把东西放在火的周围使干或使熟～炙。～面包。～肉℃～。\n(2)挨近火取暖～火。～一～手。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烤"},{"id":"glyph-kai-70e6","script":"kai","character":"烦","reading":"fán","description":"烦躁,烦闷\n通繁”。烦琐;繁多\n⒈急躁，苦闷～躁。～闷。心～。莫～恼。\n⒉多、乱、杂～琐。要言不～。～言饰辞，而无实用。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烦"},{"id":"glyph-kai-70e7","script":"kai","character":"烧","reading":"shāo","description":"⒈使物体着火～ 火。燃～。\n⒉用热能使物体受热起变化～瓦。～饭。～汤。\n⒊烹饪方法之一炒煎～炸。蘑芋～鸭子。\n⒋发热，体温升高发～。高～。～退了。\n⒌用肥过多，致使植物枯萎、死亡～了秧蔸。\n烧shào 1.放火烧野草以肥田。 2.泛指野火。 3.指彩霞。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烧"},{"id":"glyph-kai-70eb","script":"kai","character":"烫","reading":"tàng","description":"以热水温物\n被火或高温灼痛或灼伤\n用熨斗使衣服变得平整\n烫发\n⒈皮肤接触温度高的东西感到疼痛或损伤水太～。～伤。\n⒉用温度高的东西使另外的东西起变化～酒。～衣服。～头发。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烫"},{"id":"glyph-kai-70ed","script":"kai","character":"热","reading":"rè","description":"满腔热情;热心肠\n有权势的,权势显赫的\n⒈物理学上指凡能使物体温度升高的那种\"能\"叫\"热\"。\n⒉温度高，跟\"冷\"相对～天。～菜。\n⒊使温度升高将饭～一～。\n⒋盛，旺～闹。～货。～门。\n⒌情绪高，情意深～烈。～心。～忱。～爱。\n⒍羡慕眼～。\n①急切地想得到，多含贬义～中名利。\n②酷爱～中下围棋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-热"},{"id":"glyph-kai-70f9","script":"kai","character":"烹","reading":"pēng","description":"pēng：(1)煮～调（tiáo）（烹炒调制）。～饪。～茶。\n(2)一种做菜的方法，先用热油略炒之后，再加入液体调味品，迅速搅拌，随即盛出～对虾。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烹"},{"id":"glyph-kai-7109","script":"kai","character":"焉","reading":"yān","description":"yān：(1)与介词于”加代词是”相当心不在～。不复出～。\n(2)乃，才必知乱之所自起，～能治之。\n(3)文言疑问词，怎么，哪儿且～置土石？\n(4)文言助词又何戚～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-焉"},{"id":"glyph-kai-710a","script":"kai","character":"焊","reading":"hàn","description":"hàn：用熔化金属或塑料来粘合、修补金属或塑料器物～接。～工。～料。～条。～枪。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-焊"},{"id":"glyph-kai-7115","script":"kai","character":"焕","reading":"huàn","description":"huàn：光明～发。～炳（明亮）。～丽。～赫。～蔚。～然一新。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-焕"},{"id":"glyph-kai-711a","script":"kai","character":"焚","reading":"fén","description":"fén：烧～烧。～毁。～化。～香。～书坑儒。～膏继晷（膏”，油脂；晷”，日影；形容夜以继日地用功读书或努力工作）。忧心如～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-焚"},{"id":"glyph-kai-7126","script":"kai","character":"焦","reading":"jiāo","description":"jiāo：(1)物体经火烧变成黑黄色并发硬、发脆烧～。～土。～头烂额。\n(2)烦躁，着急～急。～虑。～灼。～躁不安。\n(3)酥，脆～脆。～枣。\n(4)喻干燥到极点唇～口燥。～枯。～裂。～渴。\n(5)一种质硬、多孔、发热量高的固体燃料～炭。～煤。～炼。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-焦"},{"id":"glyph-kai-7130","script":"kai","character":"焰","reading":"yàn","description":"yàn：(1)火光光～。\n(2)火苗火～。烈～。气～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-焰"},{"id":"glyph-kai-7136","script":"kai","character":"然","reading":"rán","description":"rán：(1)对，是～否。不～。不以为～。\n(2)以为对，答应，信守～纳（以为对而采纳）。～诺（许诺，信守诺言）。\n(3)这样，如此当～。～后。～则。\n(4)表示一种语气（a.表决定，犹焉，如寡人愿有言～”；b.表比拟，犹言一般，如如见其肺肝～”）。\n(5)用于词尾，表示状态显～■～。飘飘～。\n(6)古同燃”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-然"},{"id":"glyph-kai-714c","script":"kai","character":"煌","reading":"huáng","description":"huáng：光明，明亮辉～。星火～～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-煌"},{"id":"glyph-kai-714e","script":"kai","character":"煎","reading":"jiān","description":"jiān：(1)熬～药。～熬。\n(2)烹饪方法，把食物放在少量的热油里弄熟～鱼。\n(3)量词，指中药煎汁的次数头～。二～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-煎"},{"id":"glyph-kai-715e","script":"kai","character":"煞","reading":"shà；shā","description":"shā：(1)同杀”③⑤⑥⑦。\n(2)同刹”。\nshà：(1)极，很～费苦心。急～。\n(2)迷信的人指凶神～气。凶～。凶神恶～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-煞"},{"id":"glyph-kai-7164","script":"kai","character":"煤","reading":"méi","description":"méi：(1)古代的植物压埋在地底下，在不透空气或空气不足的条件下，受到地下的高温和高压年久变质而形成的黑色或黑褐色矿物～矿。～田。～层。～气。～焦油。～精。\n(2)烟气凝结的黑灰，为制墨的主要原料～炱。松～（松烟）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-煤"},{"id":"glyph-kai-7167","script":"kai","character":"照","reading":"zhào","description":"zhào：(1)光线射在物体上日～。～耀。～射。\n(2)对着镜子或其他反光的东西看自己或其他人物的影像～镜子。\n(3)摄影～相。拍～。\n(4)画像或相片小～。写～。\n(5)看顾～管。～顾。\n(6)按着，依着依～。遵～。～搬。～本宣科。\n(7)凭证护～。牌～。执～。\n(8)知晓心～不宣。肝胆相～。\n(9)通知，通告知～。～会。\n(10)对着，向着～壁。～敌人开枪。\n(11)查对对～。查～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-照"},{"id":"glyph-kai-716e","script":"kai","character":"煮","reading":"zhǔ","description":"zhǔ：把东西放在水里，用火把水烧开烹～。～饭。～字（喻书生玩味文字）。～豆燃箕（喻骨肉相残）。～鹤焚琴（喻大煞风景的事）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-煮"},{"id":"glyph-kai-717d","script":"kai","character":"煽","reading":"shān","description":"shān：同扇2”②。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-煽"},{"id":"glyph-kai-7184","script":"kai","character":"熄","reading":"xī","description":"xī：火灭，灭火～灭。～火。～灯。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-熄"},{"id":"glyph-kai-718a","script":"kai","character":"熊","reading":"xióng","description":"xióng：(1)哺乳动物，体大，尾短，四肢短而粗，脚掌大，能直立行走，也能攀树，种类很多，有棕熊”、白熊”、黑熊”等狗～（即黑熊”）。～掌。～白（熊背上的脂肪，白色，珍贵食品）。～胆（熊的胆，可入药）。～包（喻无能的人，废物）。\n(2)方言，指斥责挨了一顿～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-熊"},{"id":"glyph-kai-718f","script":"kai","character":"熏","reading":"xūn；xùn","description":"xūn：(1)气味或烟气接触物品，引申为长期接触的人或事物对品行、习惯的影响～染。～陶。～制。利欲～心。\n(2)火烟上出～蒸。\n(3)气味刺激人臭气～人。\n(4)暖和～风。\nxùn：（煤气）使人窒息中毒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-熏"},{"id":"glyph-kai-7194","script":"kai","character":"熔","reading":"róng","description":"róng：固体受热到一定温度时变成液体～化。～点。～炉。～铸。～解。～岩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-熔"},{"id":"glyph-kai-7199","script":"kai","character":"熙","reading":"xī","description":"xī：(1)光明。\n(2)兴起，兴盛。\n(3)和乐～怡。～笑。\n(4)古同禧”，福，吉祥。\n(5)古同嬉”，嬉戏。\n〔～～攘攘〕形容人来人往、喧闹纷杂的样子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-熙"},{"id":"glyph-kai-719f","script":"kai","character":"熟","reading":"shú","description":"shú：(1)食物烧煮到可吃的程度饭～了。\n(2)植物的果实或种子长成，又特指庄稼可收割或有收成成～。瓜～蒂落。\n(3)程度深～睡。～思（经久而周密地思考）。深思～虑。\n(4)做某种工作时间长了，精通而有经验～练。娴～。～习。～能生巧。\n(5)习惯，常见，知道清楚～人。～悉。～记（强记）。　　　　　　　　　　　　　　　　　　　　　　　　　轻车～路。\n(6)经过加工炼制的～铁。～皮子。～石膏。～石灰。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-熟"},{"id":"glyph-kai-71ac","script":"kai","character":"熬","reading":"áo；āo","description":"āo：烹调方法，把蔬菜等放在水里煮～白菜。\náo：(1)久煮～粥。～药。\n(2)忍受，耐苦支持煎～。～夜。～炼。\n(3)古同嗷”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-熬"},{"id":"glyph-kai-71c3","script":"kai","character":"燃","reading":"rán","description":"rán：(1)烧起火焰自～。～料。～烧。～点。～眉之急。\n(2)引火点着点～。～灯。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-燃"},{"id":"glyph-kai-71d5","script":"kai","character":"燕","reading":"yàn；yān","description":"yàn：(1)鸟类的一科，候鸟，常在人家屋内或屋檐下用泥做巢居住，捕食昆虫，对农作物有益～尔（形容新婚夫妇亲睦和美的样子）。～好（常用以指男女相爱）。～侣。～雀处（chǔ）堂（喻居安而不知远虑，临祸却不能自知）。\n(2)轻慢～朋逆其师”。\n(3)古同宴”，安闲，安乐。\n(4)古同宴”，宴饮。\nyān：(1)中国周代诸侯国名，在今河北省北部和辽宁省南部～赵。～山。～京。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-燕"},{"id":"glyph-kai-71e5","script":"kai","character":"燥","reading":"zào","description":"zào：干，缺少水分干～。～裂。～热。枯～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-燥"},{"id":"glyph-kai-7206","script":"kai","character":"爆","reading":"bào","description":"bào：(1)猛然炸裂并发出响声～豆。～花。～竹。～炸。～破。～裂。\n(2)出人意料地出现或发生～发。～满。～冷门。\n(3)烹调方法，快速油烹～鸡丁。\n(4)鼓出来眼睛～出。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爆"},{"id":"glyph-kai-722a","script":"kai","character":"爪","reading":"zhǎo；zhuǎ","description":"zhǎo：(1)指甲或趾甲趾端有～。\n(2)鸟兽的脚指鹰～。～牙（喻党羽，狗腿子）。一鳞半～。\n(3)抓。\nzhuǎ：(1)禽兽的脚（多指有尖甲的）鸡～子。狗～子。\n(2)像爪的东西，这个锅有三个～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爪"},{"id":"glyph-kai-722c","script":"kai","character":"爬","reading":"pá","description":"pá：(1)手和脚一齐着地走路，虫类行走～行。～虫（爬行动物）。～泳。\n(2)攀登～高。～升。～山。往上～（讽刺追求功名的人）。\n(3)搔～痒。～搔（搔”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爬"},{"id":"glyph-kai-7231","script":"kai","character":"爱","reading":"ài","description":"对人或事物有深厚真挚的感情\n⒈对人或事物有真诚、深厚的感情～人民。～祖国。她～教育工作。\n⒉喜好～清洁。她～唱歌。\n⒊重视，保护～惜时间。～护公物。\n⒋容易喝冷水～生病。\n⒌特指男女间的感情～情。恩～夫妻。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爱"},{"id":"glyph-kai-7235","script":"kai","character":"爵","reading":"jué","description":"jué：(1)古代饮酒的器皿，三足，以不同的形状显示使用者的身份。\n(2)君主国家贵族封号（中国古代分为公”、侯”、伯”、子”、男”五等）～位。官～。～禄（爵位和俸禄）。～士。\n(3)古同雀”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爵"},{"id":"glyph-kai-7236","script":"kai","character":"父","reading":"fù；fǔ","description":"fù：(1)爸爸，母亲的丈夫～母。～辈。～子。～兄。\n(2)对男性长辈的称呼～老（一国或一乡的长者，亦指古代乡里中管理公共事物的人）。伯～。舅～。\n女；子；母；\nfǔ：(1)老年人田～。渔～。\n(2)同甫”①。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-父"},{"id":"glyph-kai-7237","script":"kai","character":"爷","reading":"yé","description":"卷卷有爷名。\n旦辞爷娘去。\n爷娘闻女来。\n爷爷会织布、会种田、还会养牛\n对与祖父辈分相同、年龄相仿的男子的敬称。如张爷爷\n对长一辈或年长男子的尊称\n旧时对主人、上官或尊贵者的称呼\n迷信的人对神佛的称呼\n自矜\n⒈〈古〉同\"耶\"，父亲～娘均健在。\n⒊对同辈或年长男人的敬称老大～。李大～。\n⒋旧时对有权势或对有钱财之人的称呼老～。少～。\n⒌迷信者所谓\"神的称呼\"财神～、灶神～、土地～等，都是瞎编胡造的。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爷"},{"id":"glyph-kai-7238","script":"kai","character":"爸","reading":"bà","description":"bà：称呼父亲。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爸"},{"id":"glyph-kai-7239","script":"kai","character":"爹","reading":"diē","description":"diē：(1)父亲～～。～娘。\n(2)对老人或长者的尊称大～。老～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爹"},{"id":"glyph-kai-723d","script":"kai","character":"爽","reading":"shuǎng","description":"shuǎng：(1)明朗，清亮～目。\n(2)轻松，利落清～。凉～。～口。\n(3)痛快，率（shuài）直～朗。～快。～利±～。直～。\n(4)差失，违背～信。～约（失约）×厘不～。屡试不～。\n(5)干脆，索性～性。\n(6)舒服～心。～意。～适。身体不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爽"},{"id":"glyph-kai-7247","script":"kai","character":"片","reading":"piàn；piān","description":"piàn：(1)平而薄的物体卡～。名～。\n(2)切削成薄的形状～肉片。\n(3)少，零星～段（整体当中的一段）。～刻。～面。～甲不存。\n(4)指较大地区内划分的较小地区分～儿开会。\n(5)量词，指面积、范围、景象、心意等或成片的东西两～药。一～新气象。\n〔～假（jiǎ）名〕日本文所用的楷书字母。\npiān：义同（一），用于相片儿”、电影片儿”等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-片"},{"id":"glyph-kai-7248","script":"kai","character":"版","reading":"bǎn","description":"bǎn：(1)上面有文字或图形的用木板或金属等制成供印刷用的东西木～书。活字～。底～。修～。\n(2)印刷物排印一次（可多次印刷）及有关的事物排～。再～。～本。出～。～权。\n(3)报纸的一面头～头条重大新闻。\n(4)打土墙用的夹板～筑（筑土墙）。\n(5)户籍～图（原指户籍和地图，现泛指国家疆域，如我国～～辽阔”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-版"},{"id":"glyph-kai-724c","script":"kai","character":"牌","reading":"pái","description":"pái：(1)用木板或其他材料做的标志门～。路～。～子。～匾。～价。\n(2)凭证金～。银～。腰～。\n(3)产品的商标名～货。\n(4)古代兵士在战争时或现代警察在驱散示威者时用来遮护身体的东西盾～。挡箭～。\n(5)娱乐或赌博用的东西纸～。扑克～。麻将～。\n(6)神主、灵位或题着名字作为祭祀对象的木牌～位。\n(7)词曲的调名词～。曲～。～子曲。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牌"},{"id":"glyph-kai-7259","script":"kai","character":"牙","reading":"yá","description":"yá：(1)齿（古代把大齿称为牙”，现在牙”是齿的通称，亦称牙齿”）～垢。～龈。～碜。～祭。\n(2)像牙齿形状的东西抽屉～子。\n(3)特指象牙～雕。\n(4)旧时介绍买卖从中取利的人～商。～行。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牙"},{"id":"glyph-kai-725b","script":"kai","character":"牛","reading":"niú","description":"niú：(1)哺乳动物，趾端有蹄，头上长一对角，是反刍类动物，力量很大，能耕田拉车，肉和奶可食，角、皮、骨可作器物～刀小试（喻有很大的本领，先在小事情上施展一下）。～黄。～角。\n(2)星名，二十八宿之～斗（指牛宿和斗宿二星）。\n(3)喻固执或骄傲～气。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牛"},{"id":"glyph-kai-7261","script":"kai","character":"牡","reading":"mǔ","description":"mǔ：(1)雄性的鸟或兽，亦指植物的雄株，与牝”相对～牛。\n(2)锁匙～钥。\n(3)丘陵。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牡"},{"id":"glyph-kai-7262","script":"kai","character":"牢","reading":"láo","description":"láo：(1)养牲畜的圈（juàn）虎～。亡羊补～（喻事后补救还不为迟）。～笼。\n(2)古代称作祭品的牲畜太～（古代帝王、诸侯祭祀社稷时，牛、羊、豕三牲全备之称）。少～（诸侯宗庙，用羊、豕之称）。\n(3)监禁犯人的地方监～。坐～。\n(4)结实，坚固，固定～固。～稳（a.稳妥可靠；b.物体稳定，不摇晃）。～记。～不可破。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牢"},{"id":"glyph-kai-7267","script":"kai","character":"牧","reading":"mù","description":"mù：(1)放养牲口～童。畜～。～场。放～。游～。～民。～歌。～群。\n(2)治～民（治理人民）。\n(3)古代治民之官州～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牧"},{"id":"glyph-kai-7269","script":"kai","character":"物","reading":"wù","description":"wù：(1)人以外的具体的东西事～。生～。～体。货～。礼～。文～。～价。～质。地大～博。～极必反。\n(2)内容，实质言之有～。\n(3)指自己以外的人或跟自己相对的环境～议（群众的批评）。待人接～。～望所归（众望所归）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-物"},{"id":"glyph-kai-7272","script":"kai","character":"牲","reading":"shēng","description":"shēng：(1)家畜～口。～灵。～畜。\n(2)古代特指供宴飨祭祀用的牛、羊、猪三～。献～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牲"},{"id":"glyph-kai-7275","script":"kai","character":"牵","reading":"qiān","description":"⒈拉,挽着,挽引向前～牛。手～手。～着向前走。\n⒉连带，带累～连。～累。～制。～一发而动全身。\n⒊惦念，缠连～肠挂肚。意惹情～。\n⒋拘束，拘泥～于所闻。\n牵qiàn 1.挽船的绳索。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牵"},{"id":"glyph-kai-7279","script":"kai","character":"特","reading":"tè","description":"tè：(1)不平常的，超出一般的～殊。～色。～产。～权。～性。～征。～需。～技。～务。～区。～价。～例。～效。\n(2)单，单一～为（wèi）。～设。～地。～惠。～辑。～使。～赦。～约。\n(3)只，但不～如此。相如度秦王～以诈佯为予赵城，实不可得”。\n(4)三岁的兽，一说四岁的兽不狩不猎，胡瞻尔庭有悬～兮！”\n(5)公牛，亦用以借指公马和雄性的牲畜。\n(6)配偶，匹配不因旧姻，求尔新～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-特"},{"id":"glyph-kai-727a","script":"kai","character":"牺","reading":"xī","description":"⒈〈古〉作祭品用的纯毛色的牲畜。\n①〈古〉祭祀用的牲畜，色纯的叫牺，体全的叫牲。〈喻〉为正义事业而舍弃生命英勇～牲。为有～牲多壮志。\n②泛指舍弃～牲休息时间。\n牺suō 1.酒樽名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牺"},{"id":"glyph-kai-7280","script":"kai","character":"犀","reading":"xī","description":"xī：(1)哺乳动物，形状略像牛，皮粗而厚，多皱纹。角生在鼻上，产于印度一带的只生一只角，产于非洲的有两只角，可做器物，亦可入药（通称犀牛”）～角。～甲。～照。灵～。\n(2)坚固～舟（坚固的船）。～利（锐利；锋利）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-犀"},{"id":"glyph-kai-7281","script":"kai","character":"犁","reading":"lí","description":"lí：(1)耕地的农具～杖。～铧。～头。木～。\n(2)用犁耕地～地。～庭扫闾（喻彻底摧毁敌巢。亦称犁庭扫穴”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-犁"},{"id":"glyph-kai-72ac","script":"kai","character":"犬","reading":"quǎn","description":"quǎn：狗猎～。警～。～马之劳。～牙交错。～子（谦辞，对人称自己的儿子）。桀～吠尧（喻走狗一心为主子效劳）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-犬"},{"id":"glyph-kai-72af","script":"kai","character":"犯","reading":"fàn","description":"fàn：(1)抵触，违反～规。～法。～罪。～颜（旧时指冒犯君王或尊长的威严）。～讳。\n(2)违反法律的人，有罪的人～人。罪～。\n(3)侵害，进攻侵～。秋毫无～。\n(4)触发，发作～病。～愁。～疑。\n(5)做错事情～错误。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-犯"},{"id":"glyph-kai-72b6","script":"kai","character":"状","reading":"zhuàng","description":"情形;状况\n⒈样子，形态，情形～态。～况。形～。喜笑～。重病～。\n⒋诉讼～纸。告～。\n⒌特殊格式的凭证。指嘉奖、委任等奖～。委任～。军令～。\n居首位的人养鸡～元。种菜～元。\n语。状语后有时要用助词\"地\"，如\"非常地激烈\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-状"},{"id":"glyph-kai-72b9","script":"kai","character":"犹","reading":"yóu","description":"兽名★属,也叫犹猢”,形如麂\n犬子\n如同∶比\n此犹文轩之与敝舆。╠\n⒈一种猿类动物～猢。\n⒉如，同，好像～如。过～不及。虽死～生。\n⒊还，尚且记忆～新。困兽～斗。\n犹yáo 1.摇动。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-犹"},{"id":"glyph-kai-72c2","script":"kai","character":"狂","reading":"kuáng","description":"kuáng：(1)本称狗发疯，后亦指人精神失常～犬。疯～。癫～。发～。～人。\n(2)纵情任性或放荡骄恣的态度轻～。～妄（极端自高自大）。～吠（狗狂叫，借指疯狂的叫嚣）。～乱。～野。～躁。～恣。～草（草书的一种，风格狂放无羁）。\n(3)气势猛烈，超出常度～风。～飙。～热。力挽～澜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狂"},{"id":"glyph-kai-72c8","script":"kai","character":"狈","reading":"bèi","description":"传说中的一种兽,狼属。前腿特别短,走路时要爬在狼身上,没有狼,它就不能行动,所以用狼狈形容困苦或受窘的样子\n狈 bèi传说中的兽名。前腿特别短。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狈"},{"id":"glyph-kai-72d0","script":"kai","character":"狐","reading":"hú","description":"hú：(1)哺乳动物的一属，形状略像狼。毛赤黄色，性狡猾多疑，遇见攻击时肛门放出臭气，乘机逃跑。皮可做衣服（通称狐狸”）～臭（腋下臭气）。～肷（狐腋下和腹部的毛皮）。～疑（多疑）。～媚（曲意逢迎，投入所好）。～死首丘（传说狐狸将死，头必向出生的山丘。喻不忘本，亦喻对故乡的思念）。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狐"},{"id":"glyph-kai-72d7","script":"kai","character":"狗","reading":"gǒu","description":"gǒu：哺乳动物，种类很多，听觉嗅觉都很敏锐，善于看守门户，有的可以训练成军犬、警犬走～。～彘（狗和猪）。～刨（páo）（一种游泳动作）。～盗（小偷）。～腿子。～仗人势。～尾续貂（喻拿粗劣的东西接到美好的东西后面，很不相称，常指文章）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狗"},{"id":"glyph-kai-72de","script":"kai","character":"狞","reading":"níng","description":"猛烈,气势大、力量大\n通獰”。弱\n忿怒而视\n狞恶\n狞恶的神色\n狞视","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狞"},{"id":"glyph-kai-72e0","script":"kai","character":"狠","reading":"hěn","description":"hěn：(1)凶恶，残忍心～。～戾。～毒。～心。凶～。\n(2)勉强地抑制住难过的心情～着心把泪止住。\n(3)严厉地～批他一顿。\n(4)全力以赴～劲。～抓学习。\n(5)同很”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狠"},{"id":"glyph-kai-72e1","script":"kai","character":"狡","reading":"jiǎo","description":"jiǎo：(1)诡诈～猾。～诈。～黠。～辩。～赖。\n(2)多力，壮健壮～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狡"},{"id":"glyph-kai-72ec","script":"kai","character":"独","reading":"dú","description":"不见秘书心若失,百年衰病独登台","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-独"},{"id":"glyph-kai-72ed","script":"kai","character":"狭","reading":"xiá","description":"心胸狭窄","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狭"},{"id":"glyph-kai-72ee","script":"kai","character":"狮","reading":"shī","description":"犬生二子称狮”\n猛兽名\n猛，捕食羚羊、斑马等动物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狮"},{"id":"glyph-kai-72f0","script":"kai","character":"狰","reading":"zhēng","description":"zhēng：〔～狞〕样子凶恶，如面目～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狰"},{"id":"glyph-kai-72f1","script":"kai","character":"狱","reading":"yù","description":"讼案\n⒈监牢，监禁罪犯的场所监～。入～。\n⒉官司，罪案有～。冤～。文字～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狱"},{"id":"glyph-kai-72f8","script":"kai","character":"狸","reading":"lí","description":"lí：(1)即貉”。\n(2)哺乳动物，形状与猫相似，毛皮可制衣物。亦称狸子”、狸猫”、山猫”、豹猫”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狸"},{"id":"glyph-kai-72fc","script":"kai","character":"狼","reading":"láng","description":"láng：哺乳动物，形状很像狗，性残忍而贪婪，昼伏夜出，能伤害人畜。毛皮可制衣褥～狈。～奔豕突。～吞虎咽。～子野心（喻凶恶残暴的人的狂妄欲望和狠毒用心）。引～入室（喻引进坏人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狼"},{"id":"glyph-kai-730e","script":"kai","character":"猎","reading":"liè","description":"⒈捕捉禽兽打～。～获。～鸡。\n⒉打猎的～人。～枪。\n猎xī 1.见\"猎猎\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猎"},{"id":"glyph-kai-7316","script":"kai","character":"猖","reading":"chāng","description":"chāng：纵恣狂妄～狂。～披（穿衣不系带，散乱不整，引申为不遵法度，放纵自恣）。～獗。～勃（恣意妄为）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猖"},{"id":"glyph-kai-731b","script":"kai","character":"猛","reading":"měng","description":"měng：(1)气势大，力量大～将。～士。～烈。勇～。\n(2)忽然，突然～然。～省（xǐng）（亦作猛醒”）。～可（突然，陡然）。～不防。\n(3)严厉宽以济～。\n(4)凶暴苛政～于虎。～禽。～兽。～戾。～悍。\n(5)古哺乳动物，长毛的象～犸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猛"},{"id":"glyph-kai-731c","script":"kai","character":"猜","reading":"cāi","description":"cāi：(1)推测，推想～测。～断。～透。～中（zhòng）。～想。～度（duó）。\n(2)疑心，嫌疑～疑。～忌。～嫌。～拳（饮酒时助兴的游戏。亦称划拳”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猜"},{"id":"glyph-kai-7329","script":"kai","character":"猩","reading":"xīng","description":"xīng：〔～～〕哺乳动物，猿类，毛赤褐色，前肢长，无尾，吃野果。产于南洋群岛的森林中。简称猩”，如～红”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猩"},{"id":"glyph-kai-732a","script":"kai","character":"猪","reading":"zhū","description":"zhū：(1)哺乳动物，肉可食，鬃可制刷，皮可制革，粪是很好的肥料～倌。～场。～圈（juàn）。～肉。生～。野～。种（zhǒng）～。\n(2)古同潴”，水积存之处。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猪"},{"id":"glyph-kai-732b","script":"kai","character":"猫","reading":"māo；máo","description":"māo：(1)哺乳动物，面呈圆形，脚有利爪，行动敏捷，会捉老鼠。\n(2)方言，躲藏。\nmáo：〔～腰〕弯腰。亦称毛腰”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猫"},{"id":"glyph-kai-732c","script":"kai","character":"猬","reading":"wèi","description":"wèi：〔刺～〕哺乳动物，身上长有硬刺，昼伏夜出，吃鼠、蛇、昆虫等，对农业有益。简称猬”，如～集”（喻事情繁多，如刺猬的毛聚在一起）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猬"},{"id":"glyph-kai-732e","script":"kai","character":"献","reading":"xiàn","description":"下对上、卑对尊的进献\n有献于\n⒉表演，出主意～技。～殷勤。～计～策。\n献suō 1.古代一种滤酒方法。 2.雕刻。参见\"献豆\"。 3.通\"犠\"。古代酒器名。参见\"献尊\"。\n献xī 1.勺子;勺形之物。\n献yí 1.效法;模拟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-献"},{"id":"glyph-kai-7334","script":"kai","character":"猴","reading":"hóu","description":"hóu：(1)哺乳动物，种类很多，行动灵活，好群居～子。猿～。～戏。～头。～拳。～枣（中医指猕猴内脏的结石）。\n(2)喻机灵的人～儿精。\n(3)方言，乖巧，机敏（多指孩子）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猴"},{"id":"glyph-kai-733e","script":"kai","character":"猾","reading":"huá","description":"huá：奸诈狡～。～头。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猾"},{"id":"glyph-kai-733f","script":"kai","character":"猿","reading":"yuán","description":"yuán：哺乳动物，与猴相似，比猴大，颊下没有囊，没有尾巴，猩猩、大猩猩、长臂猿等都是～猴。～人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猿"},{"id":"glyph-kai-7384","script":"kai","character":"玄","reading":"xuán","description":"xuán：(1)深奥不容易理解的～妙。～奥。～理（a.深奥的道理；b.魏晋玄学所标榜的道理）。～学。～秘。\n(2)虚伪，不真实，不可靠～想。～虚。\n(3)黑色～青（深黑色）。～武（a.道教所奉的北方之神，它的形象为龟蛇合体；b.二十八宿中北方七宿的合称）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玄"},{"id":"glyph-kai-7387","script":"kai","character":"率","reading":"lǜ；shuài","description":"shuài：(1)带领～领。统～。～队。～先（带头）。～兽食人（喻暴君残害人民）。\n(2)轻易地，不细想，不慎重轻～。草～。～尔。～尔操觚（觚”，供写书用的木简；意思是轻易地下笔作文）。\n(3)爽直坦白直～。坦～。\n(4)大概，大略～常。大～。\n(5)遵循～教。～礼。\n(6)模范，楷模表～。\n(7)漂亮，俏皮（亦作帅”）这字写得～。\n(8)姓。\nlǜ：比值，两数之比效～。税～。概～。圆周～。出勤～。增长～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-率"},{"id":"glyph-kai-7389","script":"kai","character":"玉","reading":"yù","description":"yù：(1)石头的一种，质细而坚硬，有光泽，略透明，可雕琢成工艺品～石。～器。～玺（君主的玉印）。抛砖引～。金～良言。～不琢，不成器。\n(2)美，尊贵的，敬辞～泉。～液（美酒）。～言。～姿。～照（敬称别人的照片）。～宇（a.天空；b.瑰丽的宫阙殿宇）。亭亭～立。金科～律。金～其外，败絮其中。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玉"},{"id":"glyph-kai-738b","script":"kai","character":"王","reading":"wáng；wàng","description":"wáng：(1)古代一国君主的称号，现代有些国家仍用这种称号～国。～法。公子～孙。～朝（cháo）。\n(2)中国古代皇帝以下的最高爵位～公。～侯。\n(3)一族或一类中的首领山大～。蜂～。～牌（桥牌中最大的牌；喻最有力的人物或手段）。\n(4)大～父（祖父）。～母（祖母）。\n(5)姓。\nwàng：古代指统治者谓以仁义取得天下～天下。～此大邦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-王"},{"id":"glyph-kai-7396","script":"kai","character":"玖","reading":"jiǔ","description":"jiǔ：(1)似玉的黑色石。\n(2)九”的大写。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玖"},{"id":"glyph-kai-739b","script":"kai","character":"玛","reading":"mǎ","description":"用于“玛瑙”，一种具有不同颜色纹带的玉髓。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-73a9","script":"kai","character":"玩","reading":"wán","description":"wán：(1)游戏～耍。～笑。～兴（xìng）。～具。～偶。\n(2)戏弄，搬弄～弄。～狎。～花招儿。\n(3)观赏～赏。～味。瞻～。～物丧志。\n(4)可供观赏的东西古～。\n(5)轻视，忽视～忽职守。～世不恭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玩"},{"id":"glyph-kai-73ab","script":"kai","character":"玫","reading":"méi","description":"méi：〔～瑰〕a.美玉；b.落叶灌木，枝上有刺，花有紫红色、白色等多种，香味很浓，可做香料，花和根可入药。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玫"},{"id":"glyph-kai-73af","script":"kai","character":"环","reading":"huán","description":"泛指圆圈形的物品\n⒈玉圈她手上带有碧～。\n⒉圈形的东西门～。滚铁～。\n⒊围绕～绕。群山～抱。～顾周围。\n⒋射击、射箭时击中环靶的环数中十～。\n环huàn 1.击退，使退却。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-环"},{"id":"glyph-kai-73b0","script":"kai","character":"现","reading":"xiàn","description":"玉光\n次于玉的石\n现在,眼前\n⒈显出，出现，显露表～。华佗再～。昙花一～。\n⒉目前，现时～在。～代。～任。\n⒊当时，临时，当场～有的。～买～卖。～场表演。\n⒋实有的，当时可拿的～金。～货。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-现"},{"id":"glyph-kai-73b2","script":"kai","character":"玲","reading":"líng","description":"líng：形容玉碰击的声音～～作响。～～盈耳。～珑（a.金玉碰击声，如和銮～～”；b.形容器物细致精巧，如小巧～～”；c.形容人的灵活敏捷，如八面～～”此词现多形容为人处世手腕圆滑，面面俱到）。～琅。～玎。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玲"},{"id":"glyph-kai-73b7","script":"kai","character":"玷","reading":"diàn","description":"diàn：(1)白玉上面的斑点，亦喻人的缺点、过失小～（小过失）。～缺（人有缺点，如玉有斑点）。白圭之～（圭”，玉器）。\n(2)使有污点～污。～辱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玷"},{"id":"glyph-kai-73bb","script":"kai","character":"玻","reading":"bō","description":"bō：〔～璃〕a.一种质地硬而脆的透明物品，一般用细纱、石灰石、碳酸钠等混合起来，加高温熔解，冷却后制成，主要成分是二氧化碳、氧化钠和氧化钙。b.俗称某些透明的像玻璃的质料，如～～丝袜”，～～雨衣”（璃”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玻"},{"id":"glyph-kai-73ca","script":"kai","character":"珊","reading":"shān","description":"shān：〔～瑚〕由一种叫珊瑚虫的腔肠动物的外骨骼聚集而成。用珊瑚”喻珍奇之物或人才，如铁网～～”（喻搜罗珍奇之物或人才）。\n〔～～〕a.形容衣裙玉佩的声音；b.摇曳多姿的样子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-珊"},{"id":"glyph-kai-73cd","script":"kai","character":"珍","reading":"zhēn","description":"zhēn：(1)珠玉等宝物～宝。～珠。奇～异宝。席～待聘（席珍”，坐席上的宝石，喻怀才待用）。\n(2)宝贵的，贵重的～贵。～奇。～稀。～闻。～玩（贵重的供赏玩的东西）。\n(3)重视，爱惜～视。～爱。～重（zhòng）。～存。～藏（cáng）。\n(4)精美的食物～羞（亦作珍馐”）。八～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-珍"},{"id":"glyph-kai-73e0","script":"kai","character":"珠","reading":"zhū","description":"zhū：(1)蛤蚌因沙粒窜入壳内受到刺激而分泌的物质，逐层包起来形成圆粒，乳白色或略带黄色，有光泽，可做装饰品，亦可入药。称珍珠”（亦作真珠”，简称珠”）～蚌。～宝。～花。夜明～。～玑（喻优美的词藻或诗文）。～联璧合（珍珠联成串，美玉放在一起，喻人才或美好的事物聚集在一起）。\n(2)像珠子的东西汗～。泪～。露～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-珠"},{"id":"glyph-kai-73ed","script":"kai","character":"班","reading":"bān","description":"bān：(1)一群人按次序排成的行列排～。按部就～。\n(2)工作或学习的组织～组。～级。～长。～主任。领～。\n(3)军队编制中的基层单位，在排”以下。\n(4)工作按时间分成的段落，亦指工作场所早～。下～。值～。～房。\n(5)定时开行（xíng）的～车。～机。～期。\n(6)量词（a.用于人群，如这～人真能干”；b.用于定时开行的交通运输工具，如他搭下一～飞机走”）。\n(7)调回或调动（军队）～师。～兵。\n(8)古同斑”，杂色。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-班"},{"id":"glyph-kai-7403","script":"kai","character":"球","reading":"qiú","description":"qiú：(1)圆形的立体物圆～。～茎。～体。气～。煤～。\n(2)指球形的体育用品，球类运动～艺。～员。～坛。～迷。\n(3)星体，特指地球”月～。星～。誉满全～。\n(4)美玉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-球"},{"id":"glyph-kai-7405","script":"kai","character":"琅","reading":"láng","description":"láng：〔～～〕a.象声词，金石相击声；b.象声词，响亮的读书声，如书声～～”。\n〔～玕〕像珠子的美石。\n〔～玡〕山名，在中国山东省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琅"},{"id":"glyph-kai-7406","script":"kai","character":"理","reading":"lǐ","description":"lǐ：(1)物质本身的纹路、层次，客观事物本身的次序心～。肌～。条～。事～。\n(2)事物的规律，是非得失的标准，根据～由。～性。～智。～论。～喻。～解。～想。道～。～直气壮。\n(3)自然科学，有时特指物理学”～科，数～化。～疗。\n(4)按事物本身的规律或依据一定的标准对事物进行加工、处置～财。～事。管～。自～。修～。总～。\n(5)对别人的言行作出反应～睬。答～。\n(6)古代指狱官、法官。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-理"},{"id":"glyph-kai-7409","script":"kai","character":"琉","reading":"liú","description":"liú：〔～璃〕一种用铝和钠的硅酸化合物烧制的釉料，多为绿色或金黄色，用于烧制砖瓦、缸、盆以及一些工艺品（璃”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琉"},{"id":"glyph-kai-7410","script":"kai","character":"琐","reading":"suǒ","description":"也作琐琐”\n镂玉为连环叫琐,后以金属为之,作锁”。连环;锁链\n锁链形的纹饰\n加在门、箱等上面使人不能随便开启的器具◇作锁”\n锁,铁锁\n⒈玉声。\n⒉微小，零碎～事。～碎。繁～。\n⒊连环连～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琐"},{"id":"glyph-kai-7422","script":"kai","character":"琢","reading":"zhuó；zuó","description":"zhuó：雕刻玉石，使成器物，常喻用心推敲考虑、刻意求工～磨。雕～（a.雕刻玉石等；b.过分地修饰文字，使人觉得不自然，如～～之风不可长”）。～刻。～句。玉不～，不成器。\nzuó：〔～磨〕思索、考虑，如他的话我～～了很久，不明白什么意思”（磨”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琢"},{"id":"glyph-kai-7433","script":"kai","character":"琳","reading":"lín","description":"lín：美玉～珉。～琅（a.美玉，喻美好珍贵的东西，如～～满目”；b.玉石发出的声音）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琳"}];
